import java.io.*;
import java.util.*;

public class Main {
    static final PrintWriter pw = new PrintWriter(System.out);
    static final FastReader fr = new FastReader();

    public static void main(String[] args) {
        int testCount = 1;
        for (int i = 0; i < testCount; i++) {
            solveProblem();
        }
        pw.flush();
    }

    public static void solveProblem() {
        int n = readInt();
        double p = readDouble();

        int start = 0;
        int end = n - 1;
        while (start < end) {
            int mid = (start + end) / 2;
            double probability = calcProbability(mid, n);
            if (probability >= p) {
                end = mid;
            } else {
                start = mid + 1;
            }
        }
        pw.println(start);
    }

    private static double calcProbability(int m, int n) {
        long totalComb = choose(n, 3);
        double totalProb = 0.0;
        totalProb += (double) choose(m, 3);
        totalProb += (double) (choose(m, 2) * choose(n - m, 1));
        totalProb += 0.5 * (choose(m, 1) * choose(n - m, 2));
        return totalProb / totalComb;
    }

    private static long choose(int n, int c) {
        if (c > n) return 0;
        if (c == n) return 1;
        long res = 1;
        for (int i = 0; i < c; i++) {
            res *= (n - i);
        }
        for (int i = 1; i <= c; i++) {
            res /= i;
        }
        return res;
    }

    static int readInt() {
        return fr.nextInt();
    }

    static double readDouble() {
        return fr.nextDouble();
    }
}
