#include <bits/stdc++.h>
using namespace std;

static istream& input = cin;
static ostream& output = cout;

double calcProbability(int m, int n) {
    long long totalComb = 1;
    for (int i = 0; i < 3; i++) {
        totalComb *= (n - i);
    }
    for (int i = 1; i <= 3; i++) {
        totalComb /= i;
    }
    double totalProb = 0.0;
    // choose(m, 3)
    long long choose_m_3 = 1;
    for (int i = 0; i < 3; i++) {
        choose_m_3 *= (m - i);
    }
    for (int i = 1; i <= 3; i++) {
        choose_m_3 /= i;
    }
    totalProb += (double)choose_m_3;

    // choose(m, 2) * choose(n - m, 1)
    long long choose_m_2 = 1;
    for (int i = 0; i < 2; i++) {
        choose_m_2 *= (m - i);
    }
    for (int i = 1; i <= 2; i++) {
        choose_m_2 /= i;
    }
    long long choose_n_m_1 = n - m;
    totalProb += (double)(choose_m_2 * choose_n_m_1);

    // 0.5 * (choose(m, 1) * choose(n - m, 2))
    long long choose_m_1 = m;
    long long choose_n_m_2 = 1;
    for (int i = 0; i < 2; i++) {
        choose_n_m_2 *= (n - m - i);
    }
    for (int i = 1; i <= 2; i++) {
        choose_n_m_2 /= i;
    }
    totalProb += 0.5 * (double)(choose_m_1 * choose_n_m_2);

    return totalProb / (double)totalComb;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int testCount = 1;
    for (int i = 0; i < testCount; i++) {
        int n;
        double p;
        input >> n >> p;

        int start = 0;
        int end = n - 1;
        while (start < end) {
            int mid = (start + end) / 2;
            double probability = calcProbability(mid, n);
            if (probability >= p) {
                end = mid;
            } else {
                start = mid + 1;
            }
        }
        output << start << "\n";
    }
    return 0;
}

